// PROTOTYPE — wayfinder P5. Throwaway.
//
// The denied package's side of the context-binding attack. Every function here
// tries to execute denied code while a GRANTED package's async context is
// restored, and reports whether authority came with it.
//
// This is the sharpest available instrument in Deno today: TC39 AsyncContext is
// not exposed, but AsyncResource captures getAsyncContext() at construction and
// restores it in runInAsyncScope, which is the same capture-and-re-enter shape.

import * as granted from "p5-granted";
import { AsyncResource, AsyncLocalStorage, createHook } from "node:async_hooks";

const snap = (ctx) => ({
  ctx,
  whoami: String(globalThis.__permcapWhoami),
  fetch: typeof globalThis.fetch,
});

const attempt = (ctx, fn) => {
  try {
    const r = fn();
    return r ?? snap(ctx);
  } catch (e) {
    return { ctx, whoami: "threw: " + e.message, fetch: "n/a" };
  }
};

export async function stealAll() {
  const rows = [];

  rows.push({ ctx: "granted pkg holds authority (control)", whoami: "npm:p5-granted", fetch: granted.grantedSees() });
  rows.push(snap("denied pkg, sync (control)"));

  // 1. Re-enter a resource the granted package constructed.
  rows.push(
    attempt("AsyncResource.runInAsyncScope (granted-built)", () =>
      granted.makeResource().runInAsyncScope(() => snap("AsyncResource.runInAsyncScope (granted-built)"))
    )
  );
  rows.push(
    attempt("AsyncResource.runInAsyncScope (built deep in granted stack)", () =>
      granted
        .makeResourceDeepInStack()
        .runInAsyncScope(() => snap("AsyncResource.runInAsyncScope (built deep in granted stack)"))
    )
  );

  // 2. Have the granted package bind OUR function into ITS context, then call it.
  rows.push(
    attempt("AsyncLocalStorage.bind into granted context", () => {
      const bound = granted.bindIntoOurContext(() => snap("AsyncLocalStorage.bind into granted context"));
      return bound();
    })
  );

  // 3. Restore a snapshot the granted package took, and run our code inside it.
  rows.push(
    attempt("AsyncLocalStorage.snapshot restore", () => {
      const run = granted.snapshotOurContext();
      return run(() => snap("AsyncLocalStorage.snapshot restore"));
    })
  );

  // 4. Our callback invoked from deep inside the granted package's stack. P1
  //    showed the stamp follows the running script, so this must stay denied —
  //    it is the confused-deputy direction that killed --deny-module.
  rows.push(
    attempt("our callback run from granted stack", () =>
      granted.callFromOurStack(() => snap("our callback run from granted stack"))
    )
  );

  // 5. A resource we construct inside the granted package's stack, re-entered later.
  rows.push(
    attempt("AsyncResource built inside granted stack, run later", () => {
      const res = granted.callFromOurStack(() => new AsyncResource("denied-inside-granted"));
      return res.runInAsyncScope(() => snap("AsyncResource built inside granted stack, run later"));
    })
  );

  // 6. async_hooks lifecycle callbacks. These fire at scheduling boundaries,
  //    driven by the runtime rather than by a call site.
  rows.push(
    await new Promise((resolve) => {
      let done = false;
      const finish = (r) => {
        if (!done) {
          done = true;
          resolve(r);
        }
      };
      try {
        const hook = createHook({
          init() {
            hook.disable();
            finish(snap("async_hooks init callback"));
          },
        });
        hook.enable();
        // Cause an init: constructing a resource fires it.
        new AsyncResource("trigger");
        hook.disable();
        setTimeout(() => finish({ ctx: "async_hooks init callback", whoami: "<never fired>", fetch: "n/a" }), 1000);
      } catch (e) {
        finish({ ctx: "async_hooks init callback", whoami: "threw: " + e.message, fetch: "n/a" });
      }
    })
  );

  // 7. AsyncLocalStorage.bind as a *static*, binding our own context (the API
  //    error that made A1/A2 report a throw).
  rows.push(
    attempt("AsyncLocalStorage.bind (own context)", () => {
      const bound = AsyncLocalStorage.bind(() => snap("AsyncLocalStorage.bind (own context)"));
      return bound();
    })
  );

  return rows;
}
